using System.IO.Compression;
using System.Text.Json;

namespace Deep.Client.Shared.Tests.AccountDirectoryV1;

internal sealed record AccountDirectoryRestartFixture(
    string Network, string AuthorityHash, string Xna, string Dts, string LkgAdh,
    string LkgHash, string Head, string Dtt, string Adp, string Nonce, string Query)
{
    internal byte[] Bytes(string value) => Convert.FromBase64String(value);

    internal static AccountDirectoryRestartFixture Load()
    {
        using var compressed = new MemoryStream(Convert.FromBase64String(CompressedFixture));
        using var gzip = new GZipStream(compressed, CompressionMode.Decompress);
        return JsonSerializer.Deserialize<AccountDirectoryRestartFixture>(gzip)
            ?? throw new InvalidOperationException("Deterministic account-directory restart fixture is empty.");
    }

    // Public deterministic test seeds only. This is a compressed signed forward-checkpoint fixture,
    // not a production/UAT key or captured user artifact.
    private const string CompressedFixture = "";
